,1.349C5.395,1.178 5.305,1.019 5.186,0.883C5.067,0.748 4.922,0.638 4.76,0.56C4.597,0.482 4.42,0.438 4.239,0.43C3.697,0.385 2.998,1.669 2.998,1.669C2.998,1.669 1.484,4.806 0.802,6.405C0.509,7.071 0.364,7.793 0.379,8.521C0.503,11.262 0.621,14.003 0.757,16.744C0.939,20.638 1.123,24.535 1.311,28.433C1.426,30.827 1.559,33.22 1.684,35.665H3.906C4.454,32.945 5.396,30.259 5.46,27.557C5.535,23.921 5.532,6.804 5.508,1.881Z"/></svg>';
    /** A plain banknote outline for Cash on delivery -- an icon, not a brand. */
    private const COD_ICON = '<svg aria-hidden="true" focusable="false" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><rect x="2" y="6" width="20" height="12" rx="2.2"/><circle cx="12" cy="12" r="2.6"/><path d="M6 9.6v4.8M18 9.6v4.8"/></svg>';

    /**
     * Every mark, in display order, keyed by its `pay_*` setting.
     *
     * @return array<string, string>
     */
    public static function marks(): array
    {
        return self::MARKS;
    }

    /**
     * The setting keys, in display order.
     *
     * @return list<string>
     */
    public static function keys(): array
    {
        return array_keys(self::MARKS);
    }

    /**
     * The tabby and tamara marks as the product page's pay-later cards draw
     * them — Lane QA.
     *
     *   "Tabby and Tamara. two columns side by side : Split your purchase into
     *    monthly payments + Tabby logo AND Installments upto 6 months, no late
     *    fees! + tamara logo."
     *
     * DERIVED FROM THE TWO MARKS ABOVE, NOT DRAWN AGAIN: the wordmark geometry
     * is the cart's, byte for byte, so there is still one place that knows
     * what each looks like. Two things differ, both to match the cards on his
     * screenshot: the ground is a PILL (radius half the height), and tamara's
     * is the soft pastel gradient with a dark wordmark rather than the cart's
     * dark plum with a white one. The inline size goes too — the card sizes
     * the mark with a class.
     *
     * Still a constant in every sense rule 5 cares about: no argument reaches
     * the output except to choose between two literals, so `{!! !!}` prints
     * nothing a setting wrote. The gradient's id is a literal; the card is
     * drawn once per page.
     */
    public static function payLater(string $method): string
    {
        $svg = self::MARKS['pay_'.$method] ?? null;

        if (! in_array($method, ['tabby', 'tamara'], true) || $svg === null) {
            return '';
        }

        $svg = (string) preg_replace('/^<svg style="[^"]*"/', '<svg class="pdp-pl-mark"', $svg, 1);

        if ($method === 'tabby') {
            return str_replace('<rect width="49" height="18.3" rx="3" fill="#3EEBC0"/>', '<rect width="49" height="18.3" rx="9.15" fill="#3EEBC0"/>', $svg);
        }

        $svg = str_replace(
            '<rect width="55.5" height="16.3" rx="3" fill="#3B1E5E"/>',
            '<defs><linearGradient id="kbbTamaraPastel" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#FFD9C4"/><stop offset=".5" stop-color="#F7C6E3"/><stop offset="1" stop-color="#C8D4F7"/></linearGradient></defs><rect width="55.5" height="16.3" rx="8.15" fill="url(#kbbTamaraPastel)"/>',
            $svg,
        );

        return str_replace('fill="#FFFFFF"', 'fill="#1E1A22"', $svg);
    }

    /**
     * The logo a checkout payment box draws at the end of its header row.
     *
     * `$gateway` is a gateway id; anything this class has no artwork for gets
     * '' rather than a guess. Arabic gets Tamara's Arabic artwork, which its
     * SDK ships beside the Latin one. The card box carries the Visa and
     * Mastercard marks above, silenced (the label already says "card").
     */
    public static function checkoutLogo(string $gateway, bool $arabic = false, bool $tamaraWordmark = false): string
    {
        return match ($gateway) {
            'tabby' => self::TABBY_BADGE,
            'tamara' => $tamaraWordmark
                ? ($arabic ? self::TAMARA_WORDMARK_AR : self::TAMARA_WORDMARK)
                : ($arabic ? self::TAMARA_BADGE_AR : self::TAMARA_BADGE),
            'stripe' => self::silenced(self::MARKS['pay_visa']).self::silenced(self::MARKS['pay_mc']),
            'cod' => self::COD_ICON,
            default => '',
        };
    }

    /** A trust-row mark, minus its inline size and its accessible name. */
    private static function silenced(string $svg): string
    {
        $svg = (string) preg_replace('/^<svg style="[^"]*"/', '<svg aria-hidden="true" focusable="false"', $svg, 1);
        $svg = (string) preg_replace('/ role="img" aria-label="[^"]*"/', '', $svg, 1);

        return (string) preg_replace('/<title>[^<]*<\/title>/', '', $svg, 1);
    }
}
